import redis
import json
from flask import Flask, request, jsonify

# ========== 잘못된 방식: Stateful 서버 (수평 확장 불가) ==========
app_bad = Flask('bad')
sessions_in_memory = {}  # 서버 메모리에 저장 — 이 서버에만 존재!

@app_bad.route('/login_bad', methods=['POST'])
def login_bad():
    user_id = request.json['user_id']
    # 서버 1의 메모리에만 저장 → 다음 요청이 서버 2로 가면 세션 없음!
    sessions_in_memory[f'session_xyz'] = {'user_id': user_id}
    return jsonify({'session_id': 'session_xyz'})

# ========== 올바른 방식: Stateless 서버 (수평 확장 가능) ==========
app_good = Flask('good')
r = redis.Redis(host='redis-cluster', port=6379)  # 외부 공유 스토리지

@app_good.route('/login_good', methods=['POST'])
def login_good():
    user_id = request.json['user_id']
    session_id = f'sess_{user_id}_abc123'

    # Redis에 저장 → 어느 서버에서든 읽을 수 있음!
    r.setex(
        name=session_id,
        time=3600,            # 1시간 TTL
        value=json.dumps({'user_id': user_id, 'role': 'user'})
    )
    return jsonify({'session_id': session_id})

@app_good.route('/profile')
def profile():
    session_id = request.headers.get('X-Session-ID')
    # 서버 2, 3, 4 어느 서버에서든 Redis에서 읽을 수 있음
    session = r.get(session_id)
    if not session:
        return jsonify({'error': 'Unauthorized'}), 401
    return jsonify(json.loads(session))

import redis
import sqlite3
from flask import Flask, jsonify
import time

app = Flask(__name__)

def check_database():
    """DB 연결 + 간단한 쿼리로 실제 작동 확인"""
    try:
        conn = sqlite3.connect('app.db', timeout=2.0)  # 2초 타임아웃
        conn.execute('SELECT 1').fetchone()
        conn.close()
        return {'status': 'healthy', 'latency_ms': 0}
    except Exception as e:
        return {'status': 'unhealthy', 'error': str(e)}

def check_cache():
    """Redis 연결 확인"""
    try:
        r = redis.Redis(host='localhost', port=6379, socket_timeout=1.0)
        start = time.time()
        r.ping()
        latency = (time.time() - start) * 1000
        return {'status': 'healthy', 'latency_ms': round(latency, 2)}
    except Exception as e:
        return {'status': 'unhealthy', 'error': str(e)}

@app.route('/health')
def health():
    """Readiness Probe: 모든 의존성 확인"""
    checks = {
        'database': check_database(),
        'cache': check_cache(),
    }

    # 하나라도 unhealthy면 503 반환 → LB가 풀에서 제외
    is_healthy = all(
        c['status'] == 'healthy' for c in checks.values()
    )

    status_code = 200 if is_healthy else 503
    return jsonify({
        'status': 'healthy' if is_healthy else 'unhealthy',
        'checks': checks
    }), status_code

@app.route('/ping')
def ping():
    """Liveness Probe: 프로세스 생존 확인만"""
    return jsonify({'status': 'alive'}), 200

from flask import Flask, jsonify, request

app = Flask(__name__)

# ========== REST API 설계 ==========
# 사용자 정보: GET /api/v1/users/123
# 사용자 게시글: GET /api/v1/users/123/posts
# 사용자 팔로워: GET /api/v1/users/123/followers
# → 하나의 프로필 페이지를 위해 3번 요청 필요 (오버페칭 가능)

@app.route('/api/v1/users/<int:user_id>')
def get_user_rest(user_id):
    # 일관된 응답 구조 (일관성 원칙)
    return jsonify({
        'id': user_id,
        'name': 'Alice',
        'email': 'alice@example.com'
        # 불필요한 내부 DB 컬럼은 노출하지 않음 (단순성 원칙)
    })

@app.route('/api/v1/users/<int:user_id>/posts')
def get_user_posts(user_id):
    # 페이지네이션으로 성능 최적화 (성능 원칙)
    page = request.args.get('page', 1, type=int)
    limit = min(request.args.get('limit', 20, type=int), 100)  # 최대 100

    return jsonify({
        'data': [{'id': 1, 'title': 'Post 1'}],
        'pagination': {'page': page, 'limit': limit, 'total': 42}
    })

# ========== GraphQL 방식 (개념적 표현) ==========
# 단일 엔드포인트: POST /graphql
# 클라이언트가 원하는 것만 요청:
# query {
#   user(id: 123) {
#     name           ← 이것만 필요
#     posts(first: 5) { title }   ← 5개만
#   }              ← email은 이 뷰에서 불필요하니 요청 안 함
# }
print("GraphQL은 단일 요청으로 user + posts를 동시에, 필요한 필드만")

sections.content:
GraphQL은 스키마 정의가 핵심이다. 스키마는 클라이언트와 서버 사이의 계약이다.

타입 시스템 예시:

```graphql
type User {
  id: ID!
  name: String!
  email: String!
  posts: [Post!]!
}

type Post {
  id: ID!
  title: String!
  body: String!
  author: User!
}

type Query {
  user(id: ID!): User
  posts(first: Int, after: String): PostConnection!
}

type Mutation {
  createPost(title: String!, body: String!): Post!
  updatePost(id: ID!, title: String): Post!
}
```

클라이언트 쿼리 — 필요한 것만 정확히:

```graphql
query {
  user(id: "123") {
    name          # email은 이 화면에서 불필요
    posts(first: 5) {
      title       # body는 목록에서 불필요
    }
  }
}
```

GraphQL 에러 처리의 특이점: 항상 200 OK를 반환하고, `errors` 필드에 에러를 담는다. 이는 REST와 다른 방식으로, 클라이언트가 항상 `errors` 필드를 확인해야 한다.

