import jwt
import secrets
from datetime import datetime, timedelta
from flask import Flask, request, jsonify

app = Flask(__name__)
SECRET_KEY = 'your-production-secret-from-env'

def create_access_token(user_id: int, role: str) -> str:
    """짧은 수명 Access Token 생성 (15분)"""
    payload = {
        'user_id': user_id,
        'role': role,
        'exp': datetime.utcnow() + timedelta(minutes=15),  # 15분 만료
        'type': 'access'
    }
    return jwt.encode(payload, SECRET_KEY, algorithm='HS256')

def create_refresh_token(user_id: int) -> str:
    """긴 수명 Refresh Token 생성 (7일)"""
    payload = {
        'user_id': user_id,
        'exp': datetime.utcnow() + timedelta(days=7),
        'type': 'refresh',
        'jti': secrets.token_hex(16)  # 고유 ID (블랙리스트에 쓸 수 있음)
    }
    return jwt.encode(payload, SECRET_KEY, algorithm='HS256')

@app.route('/auth/login', methods=['POST'])
def login():
    data = request.json
    # 실제로는 DB에서 사용자 검증
    if data['email'] == 'user@example.com' and data['password'] == 'pass':
        access_token = create_access_token(user_id=1, role='user')
        refresh_token = create_refresh_token(user_id=1)

        response = jsonify({'access_token': access_token})
        # Refresh Token은 HTTP-only Cookie에 저장 (XSS 방어)
        response.set_cookie(
            'refresh_token', refresh_token,
            httponly=True,    # JavaScript 접근 불가
            secure=True,      # HTTPS만
            samesite='Strict' # CSRF 방어
        )
        return response
    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/auth/refresh', methods=['POST'])
def refresh():
    """Refresh Token으로 새 Access Token 발급"""
    refresh_token = request.cookies.get('refresh_token')
    try:
        payload = jwt.decode(refresh_token, SECRET_KEY, algorithms=['HS256'])
        if payload['type'] != 'refresh':
            raise ValueError('Invalid token type')
        new_access_token = create_access_token(payload['user_id'], 'user')
        return jsonify({'access_token': new_access_token})
    except jwt.ExpiredSignatureError:
        return jsonify({'error': 'Refresh token expired'}), 401

import redis
import sqlite3
import time
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
r = redis.Redis(host='localhost', port=6379)

# ========== Rate Limiting (Redis 슬라이딩 윈도우) ==========
def rate_limit(max_requests=100, window_seconds=60):
    def decorator(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            # IP 기반 키 (프로덕션: user_id 기반 권장)
            key = f'rate:{request.remote_addr}:{f.__name__}'
            current = r.incr(key)
            if current == 1:
                r.expire(key, window_seconds)  # 첫 요청에만 TTL 설정

            if current > max_requests:
                return jsonify({'error': 'Rate limit exceeded'}), 429
            return f(*args, **kwargs)
        return wrapped
    return decorator

# ========== RBAC 권한 검사 ==========
ROLE_PERMISSIONS = {
    'admin':  {'read', 'write', 'delete', 'manage_users'},
    'editor': {'read', 'write'},
    'viewer': {'read'},
}

def require_permission(permission):
    def decorator(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            user_role = request.headers.get('X-User-Role', 'viewer')
            if permission not in ROLE_PERMISSIONS.get(user_role, set()):
                return jsonify({'error': 'Forbidden'}), 403
            return f(*args, **kwargs)
        return wrapped
    return decorator

# ========== 안전한 DB 쿼리 (SQL Injection 방어) ==========
def get_user_safe(email: str):
    conn = sqlite3.connect('app.db')
    # 파라미터화 쿼리 — 사용자 입력이 절대 SQL로 해석되지 않음
    result = conn.execute(
        'SELECT id, name, email FROM users WHERE email = ?',
        (email,)  # 튜플로 전달, DB 드라이버가 이스케이프 처리
    ).fetchone()
    conn.close()
    return result

@app.route('/api/users', methods=['DELETE'])
@rate_limit(max_requests=10, window_seconds=60)  # 분당 10회만
@require_permission('delete')  # delete 권한 필요
def delete_user():
    email = request.json.get('email')
    user = get_user_safe(email)  # 안전한 쿼리
    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify({'deleted': user[0]}), 200
